// TODO: Look into if there is a way to type check what is bound to these. Currently anything can be bound to any of them but it will break as the code tries to use it.
export const Injects = {
    // Required Injects
    CoreDataList: Symbol('CoreDataList'),
    /** IAssetConfigEx: identifier to load the full CoreAssetList  */
    LocalDataList: Symbol('LocalDataList'),
    /** IBaseGameModel: DataModel representing the state of the current game as sent by the server in each Begin and Continue */
    GameModel: Symbol('GameModel'),
    /** IBaseGameSettingsModel: DataModel representing the game settings as sent by the server usually only set once in the Resume */
    GameSettings: Symbol('GameSettings'),
    /** IBaseDebugModel: DataModel of the debug options visible in the Debug Vue */
    DebugModel: Symbol('DebugModel'),
    /** IGameApp: The games main entry point initialised and rendered by the GameVue */
    GameApp: Symbol('GameApp'),
    /** Function to bind Injects.Skin, auto called by the Engine during Bootstrap */
    SkinFactory: Symbol('SkinFactory'),
    /** extends ISkinDesc: Should be bound in the SkinFactory function to ensure required bindings are setup before this */
    Skin: Symbol('Skin'),
    /** Function to bind injected components, auto called by the Engine during Bootstrap */
    ComponentsFactory: Symbol('ComponentsFactory'),
    /** extends BaseCabinet: Should be bound in the ComponentsFactory function to ensure required bindings are setup before this */
    Cabinet: Symbol('Cabinet'),
    /** The Big Win component that is in all games to show wins over a certain value, should be bound in the ComponentsFactory function */
    BigWin: Symbol('BigWin'),
    /** extends IStrings: The games strings file. Auto bound from cdn if not bound manually */
    Strings: Symbol('Strings'),
    /** Method for creating body for sending exception and metric logs */
    CreateLogBody: Symbol('CreateLogBody'),

    // Optional Injects - These have default implementations used by the Engine
    /** The root Component Vue */
    AppComponent: Symbol('AppComponent'),
    /** implements regional specific cabinet config */
    CabinetConfig: Symbol('CabinetConfig'),
    /** implements ICurrencySettings */
    CurrencySettings: Symbol('CurrencySettings'),
    /** Wraps calls to format currency */
    CurrencyFormatter: Symbol('CurrencyFormatter'),
    /** implements IGameServer */
    GameServer: Symbol('GameServer'),
    /** implements GameConfigProvider */
    GameConfigProvider: Symbol('GameConfigProvider'),
    /** Object defining the error strings for each Server response error code -e.g. { default: 'Sorry, we encountered an error', 27: Time Keeper limit reached } */
    ErrorStrings: Symbol('ErrorStrings'),
    /** implements IStake */
    Stake: Symbol('Stake'),
    /** string: Name of the game to display in the mobile-web settings page */
    SettingsPageGameName: Symbol('SettingsPageGameName'),
    /** implements IFrameConnection */
    FrameConnection: Symbol('FrameConnection'),
    /** string: name of the game prefs to use in Local Stroage */
    UserPrefsGameName: Symbol('UserPrefsGameName'),
    /** The GameVue component creating the canvas */
    GameComponent: Symbol('GameComponent'),
    /** The How To Play Vue for Desktop users */
    DesktopHTPComponent: Symbol('DesktopHTPComponent'),
    /** The How to Play Vue for Mobile users */
    MobileHTPComponent: Symbol('MobileHTPComponent'),
    /** The new vue based How to Play Vue */
    VueHTPComponent: Symbol('VueHTPComponent'),
    /** The Settings Vue for Desktop users */
    DesktopSettingsComponent: Symbol('DesktopSettingsComponent'),
    /** The Settings Vue for Mobile users */
    MobileSettingsComponent: Symbol('MobileSettingsComponent'),
    /** The SessionDataComponent Vue for showing session info over the game */
    SessionDataComponent: Symbol('SessionDataComponent'),
    /** Function which returns the desired assetQuality as a string to match the cdn folder names
     * Default: returns '1'
     */
    AssetQualityGetter: Symbol('AssetQualityGetter'),

    /** Function to bind Injects.AdminSettings, auto called by the Engine during Bootstrap */
    AdminSettingsFactory: Symbol('AdminSettingsFactory'),
    /** implements IAdminSettings, Should be bound in the AdminSettingsFactory function to ensure required bindings are setup before this */
    AdminSettings: Symbol('AdminSettings'),
    /** Function to bind Injects.Strings and Injects.ErrorStrings, auto called by the Engine during Bootstrap */
    StringsFactory: Symbol('StringsFactory'),
    /** Function to bind Injects.GameServer, auto called by the Engine during Bootstrap */
    GameServerFactory: Symbol('GameServerFactory'),
    /** implements ISettingsConfig */
    SettingsConfig: Symbol('SettingsConfig'),
    /** Function to bind Injects.ChatRulesOverride, auto called by the Engine during Bootstrap */
    ChatRulesOverrideFactory: Symbol('ChatRulesOverrideFactory'),
    /** The Chat Rules Vue, if bound used to overwrite the default Vue in our Settings package */
    ChatRulesOverride: Symbol('ChatRulesOverride'),
    /** Extends SoundManager from the arcade-client/sound-manager package */
    SoundManager: Symbol('SoundManger'),
    /** Object to store display configuration changes such as where the session information will sit on the screen */
    DisplayConfig: Symbol('DisplayConfig'),
    //** Object to store cabinet base options which could be applied to all games but different per territory */
    CabinetBaseOptions: Symbol('CabinetBaseOptions'),
    //**  Function to bind Injects.ApiClient, auto called by the Engine during Bootstrap*/
    // ApiClientFactory: Symbol('ApiClientFactory'),
    //** Object to potentially wrap platform api calls bypass host checks on legacy International cordova apps*/
    // ApiClient: Symbol('ApiClient'),
    //** Object that provides the versions on the translations files used in the new translations process. If unbound it uses the old process */
    TranslationVersions: Symbol('TranslationVersions'),
    /** Function to bind Injects.Endpoints, auto called by the Engine during Bootstrap */
    EndPointsFactory: Symbol('EndPointsFactory'),
    /** function to bund Injects.PreloadAsset a function to load extra assest such as jackpots package */
    PreloadAssetsFunction: Symbol('PreloadAssetsFunction'),
    /** The layout json file for the vue htp */
    VueHtpLayout: Symbol('VueHtpLayout'),
    SymbolPayoutData: Symbol('SymbolPayoutData'),
    /** The Auto Withdraw Server, used to handle auto withdraws in the game, currently only used in ES */
    AutoWithdrawServer: Symbol('AutoWithdrawServer'),
    AutoWithdrawServerFactory: Symbol('AutoWithdrawServerFactory'),
    /** The API version for the international engines, sent in any requests (i.e. resume begin, etc...) */
    InternationalEngineApiVersion: Symbol('InternationalEngineApiVersion'),

    // Action Menu Injects
    OperatorFeatureHighlights: Symbol('OperatorFeatureHighlights'),
    LocaleFeatures: Symbol('LocaleFeatures'),
    GameInGameManager: Symbol('GameInGameManager'),
    PrizeLeagueManager: Symbol('PrizeLeagueManager'),

    /** The operator model, used to describe the various operator specific info */
    OperatorModel: Symbol('OperatorModel')
};
